/**
 * PUNICODEX — Sync canonical lexicon to shared copies
 *
 * type/js/lexicon.js is the single source of truth.
 * This script generates:
 *   - extension/shared/lexicon.js
 *   - mobile/shared/lexicon.js
 *
 * GENERATED FILES — DO NOT EDIT BY HAND.
 * Run `npm run generate` to regenerate.
 */

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const canonical = path.join(root, 'type', 'js', 'lexicon.js');

const destinations = [
  path.join(root, 'extension', 'shared', 'lexicon.js'),
  path.join(root, 'mobile', 'shared', 'lexicon.js'),
];

const canonicalContent = fs.readFileSync(canonical, 'utf8');

const header = `// GENERATED BY scripts/sync-shared-lexicon.js — DO NOT EDIT BY HAND
// Source of truth: type/js/lexicon.js
// Run \`npm run generate\` to regenerate.
//
`;

const content = header + canonicalContent;

for (const dest of destinations) {
  // Unlink first so we never write through an existing hard link;
  // this keeps the two destinations as independent files on all platforms.
  if (fs.existsSync(dest)) {
    fs.unlinkSync(dest);
  }
  fs.writeFileSync(dest, content, 'utf8');
  console.log(`Synced ${path.relative(root, dest)}`);
}
